CREATE TABLE IF NOT EXISTS benchmark_paired_comparisons (cohort_id TEXT NOT NULL REFERENCES benchmark_cohorts(cohort_id), candidate TEXT NOT NULL, reference TEXT NOT NULL, paired_wins INTEGER NOT NULL, paired_losses INTEGER NOT NULL, paired_ties INTEGER NOT NULL, total_par2_gain_s REAL NOT NULL, note TEXT NOT NULL, PRIMARY KEY(cohort_id,candidate,reference));
CREATE TABLE IF NOT EXISTS research_findings (finding_id TEXT PRIMARY KEY, evidence_level TEXT NOT NULL CHECK(evidence_level IN ('AUDIT_CONFIRMED','AUDIT_LIMITED','HYPOTHESIS','IN_PROGRESS')), claim TEXT NOT NULL, supporting_cohort_id TEXT REFERENCES benchmark_cohorts(cohort_id), evidence_url TEXT NOT NULL, caveat TEXT NOT NULL, proposed_test TEXT);
