INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('R193 dual-live','historical audited experimental run','R193_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42295688082','102 frozen original/synthetic mixed source formulas, six arms x204 trials; dual_keep_default solved 156/204 PAR2 2927.163077 vs default 154/204 PAR2 3020.972903; positive largely one reused external original.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TA new-to-R1/R2/R193 20261107','experiment/drnas-ta-structural-holdout-20261107','IN_PROGRESS_PREPARE_PASS_SIX_SHARDS_RUNNING','https://github.com/Frane12/AndroidGameTest/actions/runs/42353551967','300 attempts planned: 30 source SHA-disjoint from R1/R2/R193 frozen manifests; five arms R153/R1A/Clean/TA portfolio/TA binary; final audit pending. Active repaired run 42353551967, prior runs 42353021436 and 42353071480 failed setup.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('ULTIMATE_T_NO_GF2_CAUSAL_ADVANTAGE','AUDIT_CONFIRMED','T Source 18/40 PAR2 1152.638359 and true Shadow 18/40 PAR2 1152.536897; no measurable benefit from source-only GF2 reasons. Derived delivers 40 certified reasons and 108 proposals on development only yet PAR2 1155.944610, worse than Clean 1153.728945.','ultimate_t_phase1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42351079758','20 reused R2 original CNFs, not globally blind; T terminal native telemetry missing in 8 timeout trials.','TD sparse lazy derived-row gating with original SHA and true matched runtime shadow.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('ULTIMATE_T_FRONTIER_EVENT_COST','AUDIT_CONFIRMED','T source rows performed 82,277,463 trail incidence updates; Shadow 82,669,868, Adaptive 82,186,161, with no active source-only reasons.','ultimate_t_phase1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42351079758','This is incidence update count, not wall CPU ns; do not claim it proves whole time cost.','Measure branch-time, incidence degree and lazy event scheduling in TD.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R2T_PORTFOLIO_POSITIVE_SAME_SOURCE','AUDIT_CONFIRMED','R2T portfolio 18/40 PAR2 1155.276228 vs R2 clean 18/40 PAR2 1168.671126; paired gain 13.394898 seconds (1.15 percent) in same source corpus.','ultimate_r2t_structural_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42350937691','Thresholds selected after source corpus analysis; not a blind discovery.','TA independent SHA-disjoint thirty-source holdout, additional binary density-only ablation.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R197_NO_BLIND_TRANSFER','AUDIT_CONFIRMED','R197 development split256 8/16 vs default 6/16, but both solved zero of 24 held-out original 2026 attempts.','r197_state_isolation_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42340570480','The held-out set may be so hard both approaches are censored; no finite speedup claim.','TK separate profiles with 30-90s follow-up on source-disjoint medium-hard originals.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R193_SYNTHETIC_SHORT_NEGATIVE','AUDIT_CONFIRMED','R193 short all six solver configurations solved all 88 tiny attempts. SAT fixed PAR2 0.174878 vs default 0.185802; dual modes added overhead.','r193short_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42333938947','Tiny synthetic microbenchmarks, not representative of hard mixed original CNFs.','Keep control families but prioritize harder SHA-originals.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('NEURAL_R5_NO_ACTUAL_GATE','AUDIT_CONFIRMED','R5 neural 66/80 PAR2 283.370511 vs Clean 66/80 283.376300; zero actual alternative activations.','neural_r5_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42338136053','No evidence of learned solver intervention; score difference smaller than microsecond-noise across instances.','Use Neural only after a measurable causal switching signal is demonstrated.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TK_LEARNED_KEEP_CAUSAL','HYPOTHESIS','R193/R194 show selective state-keeping can rescue SAT cases but R6 counterexamples show default/UNSAT profile choice can lose solved attempts.','r193dual_20261106','https://github.com/Frane12/AndroidGameTest/actions/runs/42295688082','Single or reused family effects; no broad validation of learned clauses retention.','TK source-disjoint multi-family keep/reset ablation with frozen native binary and LRAT where feasible.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_DERIVED_FRONTIER_CAUSAL','HYPOTHESIS','Derived certified XOR units/conflicts may help only if scheduled exactly when residual CDCL trail makes them novel and cheap; 82M row events shows eager scanning inefficient.','ultimate_t_phase1_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42351079758','Hypothesis not proven; no mixed-family speed advantage from T Derived yet.','TD lazy source-affine proof-checked low-degree row staging vs true runtime Shadow and Clean.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('ultimate_t2_phase2_20261107','Ultimate T2 phase 2 (10-arm causal isolation)','research_original_paired_nonblind',42352823564,20,400,'AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42352823564','T2 final 400/400; frozen R2 manifest SHA 2e6169009e985555e43e81d9b534f3bb307cef93963329694ef42459bef3c2e2; same-run only; 16 development and 24 new_to_r1 attempts per arm. Native UNSAT lacks independent LRAT; terminal telemetry missing in selected timeouts.') ON CONFLICT(cohort_id) DO UPDATE SET version=excluded.version,cohort_type=excluded.cohort_type,github_run_id=excluded.github_run_id,original_formulas=excluded.original_formulas,total_attempts=excluded.total_attempts,audit_status=excluded.audit_status,source_url=excluded.source_url,notes=excluded.notes;
