INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('TA new-to-R1/R2/R193 20261107','experiment/drnas-ta-structural-holdout-20261107','TA_FINAL_AUDIT_PASS_NOT_GLOBAL_BLIND','https://github.com/Frane12/AndroidGameTest/actions/runs/42353551967','Final 6/6 shard, 300 attempts. R153 12/60 2957.183758 PAR2, R1A 10/60 3066.988472, Clean 8/60 3201.353495, Portfolio 8/60 3154.929632, Binary 8/60 3154.981717. Portfolio vs R153 loses 197.745874 PAR2s and four solves. Freeze TA policy; no same-holdout threshold tuning.') ON CONFLICT(version) DO UPDATE SET branch=excluded.branch,status=excluded.status,last_evidence_url=excluded.last_evidence_url,notes=excluded.notes;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TA_SELECTOR_DISJOINT_REGRESSION','AUDIT_CONFIRMED','TA SHA-disjoint: Portfolio 8/60 PAR2 3154.929632 vs R153 12/60 PAR2 2957.183758, R1A 10/60 PAR2 3066.988472 and Clean 8/60 PAR2 3201.353495. 52 R1A routes, 8 clean; portfolio beats only Clean by 46.423863 PAR2 seconds, but worse than R153 by 197.745874 and four fewer solves.','ultimate_ta_disjoint_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42353551967','30 original SHA disjoint from explicit R1/R2/R193 manifests, not globally blind. 30s timeout censoring; native UNSAT not independently LRAT/FRAT checked. Route attribution requires case-wise detail.','Analyze the R153-only solves and clean-selected regressions on a development cohort, leave frozen TA untouched, test a conservative gate against new source-disjoint family holdout.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TA_BIN_ONLY_NO_GAIN','AUDIT_CONFIRMED','TA Binary 8/60 PAR2 3154.981717, Portfolio 8/60 PAR2 3154.929632; Binary 0.052085s worse over 60 paired trials (one loss). Both route totals 52 R1A and 8 clean. Neither bests R153.','ultimate_ta_disjoint_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42353551967','Small timing difference; equal aggregate route counts do not prove per-source identical routing. Held-out TA must not be tuned into development.','Prioritize cheap safe abstention on easy formulas and route disagreement attribution in separate nonholdout development samples.') ON CONFLICT(finding_id) DO UPDATE SET evidence_level=excluded.evidence_level,claim=excluded.claim,supporting_cohort_id=excluded.supporting_cohort_id,evidence_url=excluded.evidence_url,caveat=excluded.caveat,proposed_test=excluded.proposed_test;
