INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('TD_LAZY_NO_CAUSAL_GAIN','AUDIT_CONFIRMED','TD lazy source 16/40 PAR2 1235.895448 vs t_source 16/40 1235.887583 and t_shadow 16/40 1235.933106; zero frontier updates, zero completed reasons. Removing event work does not establish solver speedup.','ultimate_td_lazy_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42356438634','Nonblind reused 20 CNFs; runtime noise; no independent UNSAT LRAT.','Cost-gated GF2 proof replay only if source-certified reason is actually delivered, with clean/shadow and source-disjoint control.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('C1_COOLDOWN_NO_GAIN','AUDIT_CONFIRMED','C1 cooldown 26/100 PAR2 4362.495822 vs t_clean 26/100 4362.130685 and r153 26/100 4339.518763; 172 native reasons delivered but no causal paired improvement.','c1_certified_xor_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42358062002','TA and TD reused sources; different families behave differently; no blind validation.','Measure consumed reasons and conflict-depth effect; pre-registered source/family disjoint holdout.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R193_EXTRA_CLAUSE_REGRESSION','AUDIT_CONFIRMED','R193 hybrid4 injects 3072 certified clauses but yields 52/76 PAR2 674.862399, worse than paired R192 R28-CMS 52/76 PAR2 654.754579.','r193_gf2_cms_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42385800185','12s cap, 25 external and 13 synthetic previously seen; source-certified implication is not a proof of runtime benefit.','Ablate clause length and gate on source XOR/CNF connectivity on new source-disjoint originals.') ON CONFLICT(finding_id) DO NOTHING;
