INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R200_KISSAT_R28_SIGNAL_NOT_CONFIRMED','AUDIT_CONFIRMED','Kissat R28 15/72 PAR2 2349.000044 vs plain Kissat 12/72 PAR2 2468.759932, but source-cluster bootstrap lower95 ratio 0.99969; no robust speedup claim.','r200_disjoint24_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42401905771','20s cap, 24 sources, 3 reps; generic UNSAT no independent LRAT; not globally blind.','Independent pre-registered source/family-disjoint original CNF paired repeat with proof checks.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R200_CMS_PROSPECTIVE_NULL','AUDIT_CONFIRMED','CMS plain/R28/GF2 hybrid each 0/72 solved PAR2 4320; hybrid injected 1152 clauses at 42.151122s preprocess; no benefit.','r200_prospective_cms_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42403144676','30s cap, all timeout; PAR2 ties conceal preprocessing overhead.','Pre-registered cost-gated source-certified GF2 propagation with clean/shadow controls on solvable originals.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R201_STAGED_SMALL_PILOT','AUDIT_CONFIRMED','R201 staged 4/8 PAR2 121.483661 vs plain 4/8 PAR2 122.588972; static 4/8 PAR2 126.754795; mechanistic pilot only.','r201_staged_cms_20261107','https://github.com/Frane12/AndroidGameTest/actions/runs/42403760957','Preexposed R194 sources; 4 UNSAT per arm without independent LRAT; staging between solve calls not IPASIR-UP.','Fresh source-SHA-disjoint multi-family holdout with paired clean/shadow/static/staged and proof validation.') ON CONFLICT(finding_id) DO NOTHING;
