INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('C11B_REPAIRED_PROSPECTIVE_NEGATIVE_20261109','AUDIT_CONFIRMED','C11B original final job raised KeyError c10_structural; audit-only 42537036902 recovered 5 SHA x2 reps x5 arms. C11 triple 0/10 solved, PAR2 1200 (tie Kissat), while CaDiCaL NoElim 2/10 solved PAR2 995.448839. Frozen triple router sent all five SAT originals to CaDiCaL; no independent LRAT.','c11b_repaired_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42537036902','All SAT originals, 5 new-to-indexed-development SHA, not global blind; external solver repetition not independent seeds.','Falsify with new precommitted mixed SAT/UNSAT originals; do not tune on these five source hashes.'),
('C12_PROSPECTIVE_HYBRID_GAIN_LIMITED_20261109','AUDIT_CONFIRMED','C12 hybrid 8/16 solved PAR2 556.150674 vs Kissat 6/16 656.354789, C11 static 6/16 636.240943 and pure CaDiCaL 4/16 740.464353. R28 Kissat 6/16 656.272084 nearly identical to Kissat. One SAT source drives 2 extra solves over static route.','c12_early_bve_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42535300094','8 originals x2 repeats, not independent seeds, not global blind; SAT original witnessed, UNSAT lacks LRAT. No universal solver speedup.','Freeze policy and replicate on new SHA/families with same-seed matched control and source provenance; analyze why gate16 4/16.'),
('C8I_GATE_NEVER_ACTIVATED_20261109','AUDIT_CONFIRMED','C8I Gate16 made 0 actual decisions on 12 official sources, all 144 trials complete, all arms 2/24 solved. CaDiCaL PAR2 880.296445 vs Gate16 880.295279, noise level.','c8i_early_bve_20261108','https://github.com/Frane12/AndroidGameTest/actions/runs/42534555190','20s cap, original source all but 1 timed out per arm; no evidence of algorithmic gate benefit.','Instrument why no gate decisions before exit; pilot positive examples before new SHA-disjoint E2E.')
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('r166x_mixed_gauss_8source_20261106','R166x certified mixed Gaussian native factorial','eight_original_source_SHA_research_not_blind',42149883686,8,144,'R166X_AUDIT_PASS_RESEARCH_ONLY','https://github.com/Frane12/AndroidGameTest/actions/runs/42149883686','8 original SHA, 9 arms x2 repeats; mixed 30s/5s limits; frozen CaDiCaL and source-certified sparse Gaussian; 0/16 Clean, 2/16 Gaussian. Native reason callbacks and propagation measured, but no global blind or independent UNSAT LRAT. Independent of 25-source R165 world cross-check cohort 42149824021.') ON CONFLICT(cohort_id) DO NOTHING;
