INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('R166X_GAUSS_8SOURCE_20261106','AUDIT_CONFIRMED','R166x source-certified Gaussian 8 originals, 144 original paired trials: clean and all five direct methods 0/16 PAR2 560; Gaussian cooldown/full/watchlazy each 2/16 PAR2 540.576 (3.4686% better). Gaussian cooldown 65,803 proposals, 1,968 completed native reasons, 130 GF2 units; direct incremental 558,396,914 row events and 0 solves.','r166x_mixed_gauss_8source_20261106','https://github.com/Frane12/AndroidGameTest/actions/runs/42149883686','Research-only not globally blind; GF2 completion counts do not isolate causal gain, 2 solved attempts may be repeats of 1 original, and UNSAT independent LRAT absent.','Freeze original sources and test certified Gaussian vs true shadow and Clean on SHA-disjoint mixed CNFs; paired solved/PAR2 and consumed reasons.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('c13_official_20261109','C13 R28/BVE causal six-arm official','12_new_to_indexed_development_not_global_blind',42537515529,12,216,'C13_AUDIT_PASS_NO_INDEPENDENT_UNSAT_LRAT','https://github.com/Frane12/AndroidGameTest/actions/runs/42537515529','2026-11-09 00:25Z; commit 3261b25bd9d0d6f8bdd4cf57a8702510efa99ffd; 12 frozen original official2026 source SHA, 3 repeats x6 arms 30s; 216 E2E; SAT original witnesses verified, 3 UNSAT attempts per arm no independent LRAT; repeats not independent seeds; 8 sources activate R28; original SHA verified; not global blind; 5/6 source types? scores each 6/36; 30 timeouts each arm.') ON CONFLICT(cohort_id) DO NOTHING;
