INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('C13_OFFICIAL_CAUSAL_NEGATIVE_20261109','AUDIT_CONFIRMED','C13 original 12 official2026 SHA x3 repeats x6 policies, 216 E2E: all six methods 6/36 solved and 30/36 timeouts. Hybrid PAR2 1833.126825, CaDiCaL 1832.327424, no-R28 1832.842004, no-gate 1833.168501, Kissat 1839.522720. Neither GF2 nor BVE gate provides confirmed benefit over simpler ablations.','c13_official_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42537515529','Only 12 original sources, repeated external seeds not independent, UNSAT LRAT missing, not globally blind; 0.8s differences in ~1833s are small and not positive.','Do not promote C13; source-disjoint easy-to-medium SAT/UNSAT with verified independent seeds and certified UNSAT proof; compare no-R28 and no-gate.'),
('C13_EASY_PLANTED_ROUTING_ONLY_20261109','AUDIT_CONFIRMED','C13 easy planted SAT 216 trials all arms 36/36 solved. Hybrid PAR2 1.935681 vs C11 static 6.900285 and no-R28 6.899067; no-gate 1.936880 and Kissat 1.864059. Gain is backend selection, not proof of GF2 or BVE gate causal advantage.','c13_easy_planted_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42538022970','Synthetic planted easy SAT development, no UNSAT or mixed official validation, cannot generalize to competition benchmarks.','Pre-register new original family-disjoint medium SAT and UNSAT with independent proof before claiming robust improvement.')
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('C13_ROUTE_ELIGIBILITY_NOT_GF2_ACTIVATION_20261109','AUDIT_CONFIRMED','The C13 final field R28_activated_sources=8 is computed from source nvars<=3000 and bytes<=12MiB. Code research/c13_ablation.py routes eligible inputs to r28_kissat but trial rows do not record actual derived XOR rows, GF2 unit proof or native completed reasons. It is an eligibility/routing count, NOT evidence that eight sources executed beneficial GF2 deductions. C13 hybrid 6/36 PAR2 1833.126825 vs no-R28 6/36 PAR2 1832.842004 and pure CaDiCaL 6/36 PAR2 1832.327424.','c13_official_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42537515529','Source code and final audit reviewed; no independent native GF2 consumed-reason telemetry and no independent UNSAT LRAT.','Instrument GF2 certified row decisions, candidate reasons consumed by CDCL and fallback choice, then test against same-source no-R28 and no-gate controls on new SHA-disjoint mixed instances.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES
('c14_bve_vivify_20261109','C14 matched binary BVE vivification factorial','three_preexposed_development_sha_not_blind',42540665293,3,54,'C14_DEV3_FINAL_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42540665293','2026-11-09 00:38:44Z; commit 52529ebc2b5095a16686b5a236797dd200604e86; 3 original source SHA each 3 reps x6 arms, 30s cap. Matched binary SHA 622bea3b3524eb84c355fb51eb12efb4680c783f4ced67070782250fa57f6d0c; upstream binary differs. Source SHA: 4a3dde8588b06f42b73b96ba1e610a4b23d8cd239d44d17981c0638911c77aee (SAT, wins); dc3a17e19c6d2c076ed475b7dc342bb1474033bfd4d96f69a217f0e0e282ceac (SAT); e90397dabd4bf5e868edb9e8fe070d7d7de350a63ea70f6467e767fdf2f4f607 (UNSAT). SAT models original witnessed, UNSAT prior-reference only no independent LRAT. Repeated solver seeds not independent; no automatic promotion. C15D 42541912605 already running prospective follow-up.') ON CONFLICT(cohort_id) DO NOTHING;
