INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('C14_NO_VIVIFY_DEV3_20261109','AUDIT_CONFIRMED','C14 six-arm 3-original source SHA x3 repeats, 30s cap: no_vivify 9/9 PAR2 52.409243, matched_default 6/9 PAR2 212.125544 (75.2933% lower PAR2, 4.04748x ratio), skip_bve 6/9 PAR2 212.005010. One SAT source 4a3dde85... accounts for all 3 added solved attempts: default 3 timeouts, no_vivify 3 SAT solves total 22.629743s; skip_bve_no_vivify 3 SAT in 48.602993s. Legacy noelim 9/9 PAR2 85.626210. Same pinned 622bea3... CaDiCaL binary in matched arms; upstream baseline uses distinct binary.','c14_bve_vivify_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42540665293','Development-only 3 original sources with repeated but not independent solver seeds, SAT witnesses verified, UNSAT without independent LRAT. Mechanism is isolated intervention on vivification but cannot claim broad SAT performance or prove precise CDCL internal cause; a future C15D test is already active.','Use C15D 42541912605 development+source-disjoint controls; compare no_vivify vs matched_default, skip_bve, noelim with exact source SHA and same caps; check per-original regressions, independent seeds and proof provenance.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES
('C15D no-vivify prospective controls','experiment/drnas-c15d-no-vivify-20261109','IN_PROGRESS_SHARDS','https://github.com/Frane12/AndroidGameTest/actions/runs/42541912605','Follow-up to C14: prepare completed, 6 paired development/prospective shards running as of 2026-11-09. No numeric result or promotion until FINAL source lock/witness/PAR2 audit.')
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES
('c15d_frozen_20261109','C15D frozen matched no-vivify candidate','6_development_plus_6_new_to_indexed_not_global_blind',42541912605,12,144,'C15D_FINAL_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42541912605','2026-11-09 00:56Z: 12 original frozen source SHA, four arms x3 repeated solver seeds 30s cap. SAT original witnesses verified, published UNSAT reference agreement only (no independent LRAT). Development C14: candidate 9/9 PAR2 44.350261 vs matched 6/9 PAR2 211.261324; development C8H: candidate 9/9 PAR2 13.869957 vs matched 9/9 10.313095; prospective official: candidate 0/18 PAR2 1080 vs Kissat 3/18 PAR2 950.119349. No prospective gain or universal no-vivify promotion.'),
('mre12_exact_scc_20261109','MRE12 exact certified implication SCC quotient','12_already_evaluated_C15D_original_sha_not_blind',42544834313,12,96,'MRE12_AUDIT_ONLY_RECOVERY_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42545266420','Four original-source paired shards 24/24 each complete; original final audit failed only due download path nesting. Audit-only recovery run 42545266420 PASS, without solver rerun. 12 previously evaluated C15D source SHA, 4 arms x2 repeats, 8s cap. All SAT witnesses replay-verified on unchanged original CNF; UNSAT lacks independent LRAT, external seeds not independently varied. 506 deterministic/exhaustive mini-CNF checks + 6232 assignments PASS. One prospective official source e67d733d... has 48 replay-certified equalities, 2 quotient attempts activated but timed out; one development C14 UNSAT source loses two successes due preparatory cost. No speedup.') ON CONFLICT DO NOTHING;
