INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES
('C15D_DEV_VS_PROSPECTIVE_20261109','AUDIT_CONFIRMED','C15D frozen 144 30s E2E: no-vivify 18/36 PAR2 1138.220218 vs matched default 15/36 1301.574419 and Kissat 18/36 1184.301406. All 3 extra solves occur on already-used C14 development source(s). On 6 official prospective sources no-vivify and default solve 0/18, Kissat 3/18. No general-source benefit; C8H dev regression PAR2 13.869957 vs default 10.313095.','c15d_frozen_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42541912605','No global blind, repetitions without independent solver seeds, no independent UNSAT LRAT. Never select no-vivify by known source SHA.','Build cheap pre-solve structure-based gate and independently test against true no-vivify, default, and Kissat on new source families.'),
('MRE12_EXACT_SCC_PROOF_PRESERVED_NO_GAIN_20261109','AUDIT_CONFIRMED','MRE12 proof replayed SCC signed equivalence quotient completed 96 attempts, 12 SHA, 8s cap: baseline 10/24 PAR2 245.816939, quotient 8/24 PAR2 265.190497 (7.8813% higher), shadow 8/24 PAR2 265.318308, structural selective no-vivify 8/24 PAR2 265.246671. Selftests 506 small CNFs 6232 assignments. Only 1 previously evaluated official source produced 48 certified aliases and 2 applied quotients, neither solve; 2 baseline UNSAT successes on development source lost to preprocessing overhead in all prepass arms (even shadow). No false source SAT witness observed.','mre12_exact_scc_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42545266420','Original 42544834313 final audit failed on nested artifact path, recovered without solver reruns by 42545266420. No independent LRAT, limited original set, no global blind and not an improvement over CDCL.','Use a much cheaper proof-preserving pre-screen or certified parity-derived equality only if it can yield actual E2E gains; compare to unchanged baseline and shadow with no per-source regressions.')
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES
('MRE12 proof-replayed SCC quotient','experiment/drnas-mre12-exact-scc-quotient-20261109','AUDIT_ONLY_RECOVERY_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42545266420','96 original-source trials completed on all 4 shard jobs. Final recovered without rerunning. Baseline 10/24 PAR2 245.816939 vs exact quotient 8/24 PAR2 265.190497. Certified equalities exist on one prospective source; E2E benefit absent. No promotion.')
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('mre13_abcd_20261109','MRE13 four parallel proof-safe A/B/C/D','12_C15D_originals_reused_6_dev6_official_not_blind',42546055940,12,384,'MRE13_FINAL_384_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42546055940','4 parallel factorial variants x4 arms x12 source SHA x2 reps, original SHA unchanged, cap 8s, one frozen CaDiCaL binary, correct SAT witness check, UNSAT reference agreement but no independent LRAT, no independent solver seeds. VARIANT baselines differ due runtime scheduling. A_scan no transformation and one extra solve is not causal reduction evidence. All candidate variants official cohort 0/12 solved. No promotion.') ON CONFLICT DO NOTHING;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('scc_c1_20261109','SCC C1 native C proof-safe quotient','20_historical_official_plus_12_precommitted_synthetic_not_blind',42545609174,32,256,'SCC_C1_FINAL_256_AUDIT_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42545609174','20 previously benchmarked official2026 and 12 synthetic sources, 4 arms x2 repeat, cap 12s, no independent UNSAT LRAT, no independent solver seeds, no automatic promotion. caDiCaL baseline 32/64 PAR2 810.084311 vs SCC caDiCaL 32/64 PAR2 810.367056 (26 actual reductions); Kissat 31/64 818.000411 vs SCC Kissat 30/64 830.168194. Source-conditioned proof-safe quotient did not improve E2E.') ON CONFLICT DO NOTHING;
