INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE13_FOUR_WAY_NO_PROSPECTIVE_GAIN_20261109','AUDIT_CONFIRMED','MRE13 384/384 audited SHA paired on 12 reused originals. A_scan makes no transformation and solves 9/24 vs 8/24 A baseline (PAR2 257.261639 vs 265.261377), likely wall scheduling/cap noise, not proof of reduction. A_fast and A_balanced each 8/24 PAR2 >265.8 vs baseline 265.261377. B_packed 8/24 PAR2 267.758091 vs 267.079251 baseline (regressive). C_depth2 10/24 PAR2 245.243067 vs its baseline 10/24 248.305986 (1.23% lower). D_96 10/24 PAR2 242.251724 vs own baseline 10/24 243.922644 (0.69% lower), while D_192 regresses to 249.735120. No candidate solved any of 12 previously-evaluated official attempts; all C/D improvements confined to reused development formulas.','mre13_abcd_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42546055940','12 previously used originals, no global blind, external seeds not independently varied, no independent UNSAT LRAT; variant-specific baselines cannot be compared between variants as if exact same runtime.','Test cheap source-bound binary witness availability and provable C/D clauses on new independent SHA with >8s cap and matched shadow, pre-registered fixed policy. Reject if no new solved/robust PAR2 win.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('SCC_C1_NATIVE_QUOTIENT_NO_GAIN_20261109','AUDIT_CONFIRMED','SCC C1 native C audit 256/256 matched trials. On 32 source SHA (20 previously used official +12 synthetic), plain CaDiCaL 32/64 PAR2 810.084311 vs native SCC CaDiCaL 32/64 PAR2 810.367056 despite 26 reductions. Kissat 31/64 PAR2 818.000411 vs SCC Kissat 30/64 PAR2 830.168194, so quotient harms one solved result. Reductions alone do not imply measured E2E gain.','scc_c1_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42545609174','No independent LRAT for UNSAT and no external independently changed seeds. Sources not a source-disjoint unseen holdout.','Keep proof preserving SCC as math component, not enabled by default; require prepass cheaper than benefit and fresh original SHA paired tests.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('MRE13 A B C D proof-safe reduction','experiment/drnas-mre13-abcd-4way-20261109','FINAL_AUDIT_PASS_NO_PROMOTION','https://github.com/Frane12/AndroidGameTest/actions/runs/42546055940','384/384 completed with final audit PASS. C/D small development-only PAR2 benefits; no official source solved. No promotion.') ON CONFLICT(version) DO NOTHING;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('SCC C1 native C safe quotient','experiment/drnas-scc-c1-native-control-20261109','FINAL_AUDIT_PASS_NO_PROMOTION','https://github.com/Frane12/AndroidGameTest/actions/runs/42545609174','256/256 completed with final audit PASS. SCC route neither improves CaDiCaL nor Kissat total PAR2 and regresses one Kissat solve.') ON CONFLICT(version) DO NOTHING;
