INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('C14NV_H2_GENERALIZATION_LIMIT_20261109','AUDIT_CONFIRMED','C14NV H2 final 120/120; no-vivify 6/24 PAR2 1154.462462 vs matched default 4/24 1244.849957 (7.26% better) but below noelim 8/24 1108.236667 and Kissat 8/24 1017.063606. On original SHA e3171d818f0d919d9a7ca285d0e43f53570fefbc7a750b076ec83cd1b068133e (8d0d8518...) no-vivify alone solves both SAT attempts, PAR2 26.499054 vs each other arm timeout 120. One source provides 93.500946 seconds PAR2 gain, exceeding the net default comparison 90.387495 seconds.','c14nv_h2_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42552186899','Not global blind, two repetitions same solver seeds, native UNSAT LRAT not independently checked.','Test a structural rather than SHA-memorizing source-only selector on a newly disjoint family; include true same-binary default/noelim and Kissat controls.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE14B_C_D_NO_PORTABLE_BREAKTHROUGH_20261109','AUDIT_CONFIRMED','MRE14B D32_only 11/24 PAR2 820.863892 vs CaDiCaL 11/24 822.972355, Kissat 14/24 717.018977. MRE14C gate 11/24 PAR2 837.423664 vs CaDiCaL 11/24 836.555710 and Kissat 13/24 746.707705. MRE14D GATE_SPREAD 10/24 PAR2 873.664128 vs CaDiCaL 10/24 869.511439 and Kissat 14/24 718.486711. Different runs cannot be called paired across runs; activated C/D certificates do not prove end-to-end gain.','mre14d_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42551916446','12 reused originals, independent UNSAT LRAT absent; prep cost included; gains not generalizable.','Measure certified reasons actually used by CDCL and test one cost-gated hypothesis on new source families.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('C16P_WALL_GAIN_NOT_EQUAL_CPU_20261109','AUDIT_CONFIRMED','C16P p2 14/24 PAR2 690.508087 vs solo Kissat 12/24 804.071972 and solo no-vivify 12/24 762.422671. P2 summed child CPU 780.759962s vs solo Kissat 443.921868s (unequal CPU). C16PD immediate p2 14/24 PAR2 677.947944 vs d1 685.696723 and d4 695.635062. C16P2A p2 22/48 PAR2 1717.610225 vs CPU-pinned p2pin 20/48 1839.126068; p2fast 22/48 PAR2 1720.285154. Do not compare PAR2 across different runs as if paired.','c16p2a_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42553952760','Previously used formulas, no independent UNSAT LRAT, process races unequal CPU cost, some recovered audit-only after CI failures.','Pre-register equal CPU budget test comparing serial portfolio/1-core p2 with same-source frozen seeds, measure both CPU and wall.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO benchmark_cohorts (cohort_id,version,cohort_type,github_run_id,original_formulas,total_attempts,audit_status,source_url,notes) VALUES ('mre_x6_20261109','MRE X6 shift dose placement','reused_4SAT_development_not_blind',42555463975,4,128,'MRE_X6_FINAL_PASS','https://github.com/Frane12/AndroidGameTest/actions/runs/42555463975','X6 2026-11-09 final 128/128 E2E 4 frozen original previously used source SHA, four numeric seeds, 8 arms cap 12 seconds. 768 additional bounded CDCL diagnostic measurements are not E2E and are excluded from total_attempts. All SAT original witness checked; all 4 original sources SAT, not mixed UNSAT, not global blind. Exact source SHA: 220bb8aa093e502c47afcdac3140d67c sha256=69aa8b6bb96a5952fedf1007994b4255d06f7e32023390bc4c342b1b30a0356a; fdfcd52a21824b7181d66672f283ba04 sha256=7f25d0862e92fb60d957ea903ded020ec2b83b2ceec2ba4bf015bdcb1d4c3ac1; 695d8f6a2ee6e89e5a4f5d94abc3aca6 sha256=eb9a4740b712b149f08d5b430ae5907109eac3f231ce549a281703bc8e0965fb; 578f9377bfbfcc6ea3a18eb630667956 sha256=818eea0ab4e59102c589549d3ca487bf7c8a03e1e51644a126cba75a911e53de. No watch-order/LBD/restart traces to isolate full mechanism.') ON CONFLICT DO NOTHING;
