INSERT INTO research_findings (finding_id,evidence_level,claim,supporting_cohort_id,evidence_url,caveat,proposed_test) VALUES ('MRE_X6_SHIFT_CAUSAL_CANDIDATE_20261109','AUDIT_CONFIRMED','MRE X6 128 E2E original 13/16 PAR2 110.424807, spread100 16/16 PAR2 34.860892, shift1 16/16 PAR2 20.716648, spread_shifted 16/16 PAR2 14.284037. Censored PAR2 ratio 7.730644x, not uncensored speedup. SAT source 220bb8aa093e502c47afcdac3140d67c original 1/4 PAR2 72.528345 but spread_shifted 4/4 PAR2 1.674038; first aggregate propagation divergence at 10 conflicts in bounded separate diagnostics. Reverse copies 13/16 PAR2 109.972296 nearly baseline; placement matters.','mre_x6_20261109','https://github.com/Frane12/AndroidGameTest/actions/runs/42555463975','Four reused development SAT-only source SHA, no independent mixed UNSAT benchmark, no blind holdout, no watch/LBD/restart causal traces. 768 diagnostics excluded from 128 PAR2 trials.','Use newly family/source-disjoint mixed original CNF, frozen native binary/seeds and ablation plus early-CDCL consumed-propagation/LBD/restart traces. Do not infer broad speedup from current selected 4 sources.') ON CONFLICT(finding_id) DO NOTHING;
INSERT INTO build_status (version,branch,status,last_evidence_url,notes) VALUES ('MRE X6 shift-dose causal','experiment/drnas-mre-x6-shift-dose-causal-20261109','FINAL_AUDIT_PASS_128_E2E','https://github.com/Frane12/AndroidGameTest/actions/runs/42555463975','X6 2026-11-09 final 128/128 E2E 4 frozen original previously used source SHA, four numeric seeds, 8 arms cap 12 seconds. 768 additional bounded CDCL diagnostic measurements are not E2E and are excluded from total_attempts. All SAT original witness checked; all 4 original sources SAT, not mixed UNSAT, not global blind. Exact source SHA: 220bb8aa093e502c47afcdac3140d67c sha256=69aa8b6bb96a5952fedf1007994b4255d06f7e32023390bc4c342b1b30a0356a; fdfcd52a21824b7181d66672f283ba04 sha256=7f25d0862e92fb60d957ea903ded020ec2b83b2ceec2ba4bf015bdcb1d4c3ac1; 695d8f6a2ee6e89e5a4f5d94abc3aca6 sha256=eb9a4740b712b149f08d5b430ae5907109eac3f231ce549a281703bc8e0965fb; 578f9377bfbfcc6ea3a18eb630667956 sha256=818eea0ab4e59102c589549d3ca487bf7c8a03e1e51644a126cba75a911e53de. No watch-order/LBD/restart traces to isolate full mechanism.') ON CONFLICT(version) DO NOTHING;
